/**
 * Execute governance review through the authority layer.
 * 
 * This is the single entry point for all governance decisions.
 * It orchestrates external + internal Gravito, merges decisions,
 * records audit trail, and fires alerts.
 */
export async function executeGovernanceAuthority(
  input: AuthorityLayerInput,
): Promise<AuthorityLayerResult> {
  const startTime = Date.now();
  const enableExternal = input.enableExternal !== false && _config.externalEnabled;

  log.info(
    `[Authority] Starting governance review — surface: ${input.surfaceType}, ` +
    `regulated: ${input.regulated}, external: ${enableExternal}`
  );

  // ========================================================================
  // Step 1: Call External Gravito (if enabled)
  // ========================================================================
  let externalResult: GravitoExternalReviewResult | null = null;
  let externalDecision: GovernanceDecision | null = null;

  if (enableExternal) {
    // Validate content length
    const contentToReview = input.content.length > _config.maxContentLength
      ? input.content.slice(0, _config.maxContentLength)
      : input.content;

    const artifactType = _config.surfaceToArtifactType[input.surfaceType] || 'copy';

    externalResult = await reviewContentExternal({
      content: contentToReview,
      artifactType,
      mode: input.regulated ? 'release_gate' : 'pr_review',
      surfaceType: input.surfaceType,
    });

    externalDecision = mapExternalGravitoToDecision(externalResult);

    if (externalResult.success) {
      log.info(
        `[Authority] External Gravito succeeded — score: ${externalDecision.score}, ` +
        `approved: ${externalDecision.approved}, latency: ${externalResult.latencyMs}ms`
      );
    } else {
      log.warn(
        `[Authority] External Gravito failed — source: ${externalResult.source}, ` +
        `error: ${externalResult.error}, latency: ${externalResult.latencyMs}ms`
      );
    }
  }

  // ========================================================================
  // Step 2: Call Internal Gravito (always runs as fallback/comparison)
  // ========================================================================
  let internalDecision: GovernanceDecision;
  let internalLatencyMs = 0;

  try {
    const { callGravitoInline } = await import('./co-processor/gravito-inline-client');

    // Build minimal signals for internal Gravito
    const signals = {
      classification: {
        domain: input.domain,
        isRegulated: input.regulated,
      },
    };

    const heuristicAnalysis = {
      score: 75,
      passed: true,
      issues: [],
    };

    const internalStart = Date.now();
    const internalResult = await callGravitoInline(input.content, signals, heuristicAnalysis);
    internalLatencyMs = Date.now() - internalStart;

    internalDecision = mapInternalGravitoToDecision(internalResult);

    log.info(
      `[Authority] Internal Gravito completed — score: ${internalDecision.score}, ` +
      `approved: ${internalDecision.approved}, mode: ${internalResult.governanceMode}, ` +
      `latency: ${internalLatencyMs}ms`
    );
  } catch (err) {
    // Internal Gravito also failed — this is critical
    log.error(`[Authority] Internal Gravito ALSO failed: ${err}`);

    internalDecision = {
      decisionId: `internal_error_${Date.now()}`,
      approved: !input.regulated, // Fail closed for regulated
      requiresGate: true,
      advisoryOnly: false,
      score: input.regulated ? 0 : 50,
      severity: input.regulated ? 'fail_closed' : 'warning',
      reasons: [{
        id: 'internal_gravito_error',
        category: 'availability',
        severity: 'critical',
        description: `Internal Gravito failed: ${err instanceof Error ? err.message : String(err)}`,
      }],
      patches: [],
      source: input.regulated ? 'fail_closed' : 'degraded_engine',
      metadata: {
        gravitoRunId: `internal_error_${Date.now()}`,
        decisionTraceId: `internal_error_trace_${Date.now()}`,
        policyVersion: 'error',
        latencyMs: 0,
        fallback: true,
        fallbackReason: err instanceof Error ? err.message : String(err),
        retryCount: 0,
        timestamp: Date.now(),
      },
    };
  }

  // ========================================================================
  // Step 3: Merge Decisions
  // ========================================================================
  const mergedDecision = mergeGovernanceDecisions(
    externalDecision,
    internalDecision,
    { regulated: input.regulated, surfaceType: input.surfaceType },
  );

  const totalLatencyMs = Date.now() - startTime;

  log.info(
    `[Authority] Merged decision — strategy: ${mergedDecision.mergeInfo.mergeStrategy}, ` +
    `authority: ${mergedDecision.mergeInfo.authoritySource}, ` +
    `score: ${mergedDecision.score}, approved: ${mergedDecision.approved}, ` +
    `severity: ${mergedDecision.severity}, total latency: ${totalLatencyMs}ms`
  );

  // ========================================================================
  // Step 4: Build Audit Entry
