export function listJobs(opts?: {
  limit?: number;
  statusFilter?: string;
}): Array<{
  jobId: string;
  toolName: string;
  status: string;
  startedAt: number;
  completedAt: number | null;
  elapsedMs: number;
}> {
  const limit = opts?.limit || 20;
  const statusFilter = opts?.statusFilter;

  let jobs = Array.from(_activeJobs.values());

  if (statusFilter) {
    jobs = jobs.filter(j => j.status === statusFilter);
  }

  // Sort by most recent first
  jobs.sort((a, b) => b.startedAt - a.startedAt);

  return jobs.slice(0, limit).map(j => ({
    jobId: j.jobId,
    toolName: j.toolName,
    status: j.status,
    startedAt: j.startedAt,
    completedAt: j.completedAt,
    elapsedMs: (j.completedAt || Date.now()) - j.startedAt,
  }));
}

